 @Override public void tick(){client.tick();if(legacyBrowse!=null){legacyBrowse.tick();if(!legacyBrowse.busy()){notice=legacyBrowse.result;legacyBrowse.detach();legacyBrowse=null;}}if(boxes[0]==null)return;for(int n=0;n<2;n++)if(boxes[n]!=null&&displayed[n]!=null){Draft d=displayed[n];boxes[n].setEditable(client.connected()&&!ioBusy&&d.editable&&!d.blocked&&!d.replica.pending());}long now=System.nanoTime();if(now-cacheAt>500_000_000L){cacheAt=now;saveAll();}if(!idle())return;for(Draft d:drafts.values())if(!d.blocked&&(d.replica.pending()||d.dirty()&&now-edited>350_000_000L)){submit(d);return;}Draft d=drafts.get(active);if(d!=null&&!d.blocked&&!d.dirty()&&now-poll>350_000_000L){poll=now;var ids=d.replica.document().visibleIds();int cp=cursor(d.doc);int[] selection=d.doc.orderedSelection();if(selection!=null)cp=offset(d.doc,selection[0],selection[1]);var anchor=cp<=0||ids.isEmpty()?CollaborativeDocument121.ROOT:ids.get(Math.min(cp,ids.size())-1);int end=selection==null?cp:offset(d.doc,selection[2],selection[3]);var selected=end<=0||ids.isEmpty()?CollaborativeDocument121.ROOT:ids.get(Math.min(end,ids.size())-1);send("POLL",Map.of("path",active,"anchor",WorkspaceCodec122.id(anchor),"selection",WorkspaceCodec122.id(selected),"color",Integer.toString(color),"sequence",Long.toString(++sequence),"session",presence.toString()),a->{if(!a.getOrDefault("result","").equals("OK")){d.blocked=true;notice=a.getOrDefault("result","INVALID");}else file(a,false,false);});}}
 private record Mark(CollaborativeDocument121.Id caret,CollaborativeDocument121.Id start,CollaborativeDocument121.Id end){}
 private static int offset(EditorDocument d,int line,int col){int n=0;for(int i=0;i<line;i++)n+=d.line(i).codePointCount(0,d.line(i).length())+1;String s=d.line(line);int c=Math.min(col,s.length());if(c>0&&c<s.length()&&Character.isLowSurrogate(s.charAt(c)))c--;return n+s.codePointCount(0,c);}
 private static int cursor(EditorDocument d){return offset(d,d.cursorLine(),d.cursorCol());}
 private static CollaborativeDocument121.Id at(Draft d,int cp){var ids=d.replica.document().visibleIds();return cp<=0||ids.isEmpty()?CollaborativeDocument121.ROOT:ids.get(Math.min(cp,ids.size())-1);}
 private static Mark mark(Draft d){int[] sel=d.doc.orderedSelection();return new Mark(at(d,cursor(d.doc)),sel==null?null:at(d,offset(d.doc,sel[0],sel[1])),sel==null?null:at(d,offset(d.doc,sel[2],sel[3])));}
